using Geeratya.Core.Help;
using Geeratya.Core.Keymap;
using Geeratya.Core.Mouse;
using Geeratya.Core.State;
using Geeratya.Core.Text;

namespace Geeratya.Tui.Rendering;

/// <summary>
/// The help popup (<c>docs/ux.md</c>, "Help"): a framed box over the view of the tab with the section names in a menu
/// on the left (the active one marked <c>&gt; </c>) and the page generated by <see cref="HelpPages"/> beside it,
/// scrolled. The filter shows in the title. Pure.
/// </summary>
public static class HelpOverlay
{
    private const string Title = "Help";
    private const string ActiveMark = "> ";
    private const string IdleMark = "  ";
    private const string Divider = "│";
    private const string FilterPrefix = "/ ";
    private const int MaxBoxWidth = 96;
    private const int NarrowBoxWidth = 24;
    private const int Margin = 4;
    private const int MinimumBoxHeight = 4;
    private const int MinimumBoxWidth = 8;
    private const int TopGap = 1;
    private const int BottomGap = 1;
    private const int MenuGap = 1;
    private const int ContinuationIndent = 13;

    public static bool Applies(AppState state)
    {
        return state.Mode == InputMode.Help && !state.MessagesOpen;
    }

    /// <summary>The state the view behind the popup is drawn for: as in Normal mode.</summary>
    public static AppState Underlying(AppState state)
    {
        return state with { Mode = InputMode.Normal };
    }

    /// <summary>
    /// Draws the popup over <paramref name="body"/> (<paramref name="height"/> lines); the section names are noted in
    /// <paramref name="regions"/> (body rows, the frame shifts them below the header).
    /// </summary>
    public static IReadOnlyList<StyledLine> Compose(
        IReadOnlyList<StyledLine> body,
        AppState state,
        KeymapTable keymap,
        int width,
        int height,
        List<OverlayRegion>? regions = null)
    {
        var boxWidth = width >= NarrowBoxWidth ? Math.Min(width - Margin, MaxBoxWidth) : width;
        var boxHeight = height - TopGap - BottomGap;
        var top = TopGap;

        if (boxHeight < MinimumBoxHeight)
        {
            boxHeight = height;
            top = 0;
        }

        if (boxWidth < MinimumBoxWidth || boxHeight < MinimumBoxHeight)
        {
            return body;
        }

        var left = (width - boxWidth) / 2;
        var rows = boxHeight - 2;
        var names = HelpPages.Names(state, keymap);
        var current = HelpPages.Current(state, keymap);
        var inner = boxWidth - 4;
        var menuCells = Math.Min(names.Max(DisplayWidth.Of) + ActiveMark.Length, Math.Max(1, inner / 2));
        var pageWidth = Math.Max(0, inner - menuCells - MenuGap - Divider.Length - MenuGap);
        var first = FirstVisible(names.Count, current, rows);
        var page = HelpPages.Lines(state, keymap)
            .Skip(state.HelpScroll)
            .SelectMany(line => Wrap(line, pageWidth))
            .Take(rows)
            .ToList();
        var box = new List<StyledLine> { OverlayBox.Top(boxWidth, TitleText(state, boxWidth)) };

        for (var row = 0; row < rows; row++)
        {
            var index = first + row;
            var menu = MenuRow(names, index, current, menuCells);
            var text = row < page.Count ? StyledLine.Of(page[row]) : StyledLine.Empty;
            var spans = new List<StyledSpan>(menu.Spans)
            {
                new(new string(' ', MenuGap), TextRole.Body),
                new(Divider, TextRole.Muted),
                new(new string(' ', MenuGap), TextRole.Body),
            };

            spans.AddRange(StyledLines.Fit(text, pageWidth).Spans);
            box.Add(OverlayBox.Wall(new StyledLine(spans), boxWidth - 2));
        }

        box.Add(OverlayBox.Bottom(boxWidth));

        OverlayBox.Cover(regions, top, left, boxWidth, box.Count);

        for (var row = 0; row < rows && first + row < names.Count; row++)
        {
            regions?.Add(new OverlayRegion(MouseTarget.HelpPage, top + 1 + row, left + 2, menuCells, 1, first + row));
        }

        var result = OverlayBox.Backdrop(body);

        for (var index = 0; index < box.Count && top + index < result.Count; index++)
        {
            result[top + index] = OverlayBox.Over(result[top + index], box[index], left, width);
        }

        return result;
    }

    private static string TitleText(AppState state, int boxWidth)
    {
        if (state.HelpFilter.Length == 0 && !state.HelpFiltering)
        {
            return Title;
        }

        var room = Math.Max(1, boxWidth - 8 - Title.Length - FilterPrefix.Length);
        var window = PromptWindow.Of(new PromptText(state.HelpFilter, state.HelpFilterBack), room);

        if (!state.HelpFiltering)
        {
            return $"{Title}  {FilterPrefix}{window.Before}{window.After}";
        }

        return $"{Title}  {FilterPrefix}{window.Before}{window.Caret}{window.After}";
    }

    private static StyledLine MenuRow(IReadOnlyList<string> names, int index, int current, int cells)
    {
        return index < names.Count
            ? MenuEntry(names[index], index == current, cells)
            : StyledLine.Of(new string(' ', cells));
    }

    /// <summary>
    /// A page row cut into rows of at most <paramref name="width"/> columns at spaces; the continuation rows are
    /// indented under the title of the row, so nothing is lost at 80 columns.
    /// </summary>
    private static List<string> Wrap(string text, int width)
    {
        var rows = new List<string>();
        var indent = new string(' ', Math.Min(ContinuationIndent, Math.Max(0, width / 2)));
        var rest = text;

        while (width > 0 && TextWidth.Of(rest) > width)
        {
            var head = TextWidth.Fit(rest, width);
            var space = head.LastIndexOf(' ');
            var cut = space > indent.Length ? space : head.Length;

            rows.Add(rest[..cut].TrimEnd());
            rest = $"{indent}{rest[cut..].TrimStart()}";
        }

        rows.Add(rest);

        return rows;
    }

    private static StyledLine MenuEntry(string name, bool active, int cells)
    {
        var text = $"{(active ? ActiveMark : IdleMark)}{name}";
        var role = active ? TextRole.Selected : TextRole.Muted;
        var line = StyledLines.Fit(StyledLine.Of(text, role), cells);
        var missing = cells - line.Spans.Sum(span => DisplayWidth.Of(span.Text));

        return missing <= 0 ? line : new StyledLine([.. line.Spans, new StyledSpan(new string(' ', missing), TextRole.Body)]);
    }

    // The first menu entry shown: the active one stays inside the rows.
    private static int FirstVisible(int count, int current, int rows)
    {
        return rows <= 0 || current < rows ? 0 : Math.Min(current - rows + 1, Math.Max(0, count - rows));
    }
}
